import { useDrawListStore } from "@/app/store/draw-list";
import Locale from "@/app/locales";
import { IconButton } from "@/app/components/button";
import CloseIcon from "@/app/icons/close.svg";
import { Path } from "@/app/constant";
import { useNavigate } from "react-router-dom";
import { ErrorBoundary } from "./error";
import { List, Image, Tooltip } from "antd";

import styles from "./draw-list.module.scss";
import { useMobileScreen } from "@/app/utils";

export function DrawList() {
  const navigate = useNavigate();
  const drawListStore = useDrawListStore();
  const isMobileScreen = useMobileScreen();
  const fallback =
    "data:image/png;base64,";

  return (
    <ErrorBoundary>
      <div className="window-header" data-tauri-drag-region>
        <div className="window-header-title">
          <div className="window-header-main-title">
            {Locale.Midjourney.DrawListTitle}
          </div>
          <div className="window-header-sub-title">
            {Locale.Midjourney.DrawListSubTitle(drawListStore.items.length)}
          </div>
        </div>
        <div className="window-actions">
          <div className="window-action-button"></div>
          <div className="window-action-button"></div>
          <div className="window-action-button">
            <IconButton
              icon={<CloseIcon />}
              onClick={() => navigate(Path.Home)}
              bordered
            />
          </div>
        </div>
      </div>
      <div className={styles["draw-list"]}>
        <List
          grid={{ gutter: isMobileScreen ? 5 : 16 }}
          dataSource={drawListStore.items}
          renderItem={(item, index) => (
            <List.Item key={index}>
              <Tooltip title={<span>{item.prompt ?? ""}</span>} color={"cyan"}>
                <Image
                  width={isMobileScreen ? 88 : 155}
                  src={item.imgUrl}
                  fallback={fallback}
                />
              </Tooltip>
            </List.Item>
          )}
        ></List>
      </div>
    </ErrorBoundary>
  );
}
